// Generated by AI (UnitTest MCP)
//! Merge verification against a real repository.
//!
//! These build an actual git repository rather than mocking git, because the
//! whole value of ADR-0058 is that git answers the question and we do not. A
//! mock would assert that our own beliefs about `merge-base --is-ancestor` are
//! self-consistent, which is not the property under test.

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::merge::verify_merge;

/// Run git in the fixture, with the parent's git environment cleared.
///
/// Not optional. A child git that inherits `GIT_DIR`, `GIT_INDEX_FILE` or the
/// object-directory variables operates on the *parent* repository, so a fixture
/// commit lands in the real checkout. That happened in this repository once
/// already (PR #21) and cost a restore.
fn git(root: &Path, args: &[&str]) -> String {
    let output = Command::new("git")
        .args(args)
        .current_dir(root)
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .env_remove("GIT_COMMON_DIR")
        .env_remove("GIT_INDEX_FILE")
        .env_remove("GIT_OBJECT_DIRECTORY")
        .env_remove("GIT_ALTERNATE_OBJECT_DIRECTORIES")
        .output()
        .expect("git runs");
    assert!(
        output.status.success(),
        "git {:?} failed: {}",
        args,
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

fn write(root: &Path, relative: &str, contents: &str) {
    let path = root.join(relative);
    std::fs::create_dir_all(path.parent().expect("has a parent")).expect("mkdir");
    std::fs::write(path, contents).expect("write");
}

/// A repository with `main`, plus a side branch merged into it.
///
/// Returns the fixture root, the merge commit on `main`, and a commit that was
/// never merged.
struct Fixture {
    root: PathBuf,
    merged: String,
    unmerged: String,
}

fn fixture(name: &str) -> Fixture {
    let root = std::env::temp_dir().join(format!("lodestar-merge-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).expect("mkdir");

    git(&root, &["init", "--initial-branch=main"]);
    git(&root, &["config", "user.email", "fixture@example.invalid"]);
    git(&root, &["config", "user.name", "fixture"]);
    git(&root, &["config", "commit.gpgsign", "false"]);

    write(&root, "README.md", "base\n");
    git(&root, &["add", "README.md"]);
    git(&root, &["commit", "-m", "base"]);

    // Work on a side branch, merged into main: this is the shape ADR-0058 cares
    // about, a commit that landed.
    git(&root, &["checkout", "-b", "feature"]);
    write(&root, "crates/thing/src/lib.rs", "pub fn thing() {}\n");
    git(&root, &["add", "crates/thing/src/lib.rs"]);
    git(&root, &["commit", "-m", "feat: the thing"]);
    let merged = git(&root, &["rev-parse", "HEAD"]);
    git(&root, &["checkout", "main"]);
    git(&root, &["merge", "--no-ff", "--no-edit", "feature"]);

    // Work that never landed, on a branch main cannot reach.
    git(&root, &["checkout", "-b", "abandoned"]);
    write(&root, "crates/thing/src/other.rs", "pub fn other() {}\n");
    git(&root, &["add", "crates/thing/src/other.rs"]);
    git(&root, &["commit", "-m", "feat: never merged"]);
    let unmerged = git(&root, &["rev-parse", "HEAD"]);
    git(&root, &["checkout", "main"]);

    Fixture {
        root,
        merged,
        unmerged,
    }
}

#[test]
fn a_merged_commit_inside_the_declared_scope_verifies() {
    let f = fixture("accepts");
    let scope = vec!["crates/thing/**".to_string()];

    let proof = verify_merge(&f.root, &f.merged, "main", &scope).expect("verifies");

    assert_eq!(proof.commit, f.merged, "the resolved hash is returned");
    assert!(
        proof
            .changed_paths
            .contains(&"crates/thing/src/lib.rs".to_string()),
        "the touched paths are reported: {:?}",
        proof.changed_paths
    );
}

// An abbreviation must resolve to the same commit, because git resolves it
// rather than us pattern-matching the string.
#[test]
fn an_abbreviated_hash_resolves_to_the_full_commit() {
    let f = fixture("abbrev");
    let scope = vec!["crates/thing/**".to_string()];

    let proof = verify_merge(&f.root, &f.merged[..8], "main", &scope).expect("verifies");

    assert_eq!(proof.commit, f.merged);
}

// The load-bearing refusal: work that has not landed is not evidence that it
// shipped. Without this the whole verb is a rubber stamp.
#[test]
fn a_commit_that_never_merged_is_refused() {
    let f = fixture("unmerged");
    let scope = vec!["crates/thing/**".to_string()];

    let error = verify_merge(&f.root, &f.unmerged, "main", &scope)
        .expect_err("an unmerged commit must be refused");

    let message = error.to_string();
    assert!(
        message.contains("not reachable"),
        "the refusal must say why: {message}"
    );
}

// A commit that touched none of the task's paths is somebody else's work, and
// accepting it is exactly the laundering ADR-0058 warns about.
#[test]
fn a_commit_outside_the_declared_scope_is_refused() {
    let f = fixture("outside");
    let scope = vec!["editors/vscode/**".to_string()];

    let error = verify_merge(&f.root, &f.merged, "main", &scope)
        .expect_err("a commit outside scope must be refused");

    assert!(error.to_string().contains("declared scope"), "{error}");
}

// A task that declared nothing would otherwise accept any merged commit in the
// repository as its own receipt, so the caller is told rather than waved past.
#[test]
fn a_task_with_no_declared_scope_is_told_rather_than_waved_through() {
    let f = fixture("noscope");

    let error =
        verify_merge(&f.root, &f.merged, "main", &[]).expect_err("an empty scope must be refused");

    assert!(error.to_string().contains("no path scope"), "{error}");
}

// A hash that does not resolve is refused with the command that produces a real
// one, because the caller is the only one who can supply a correct value.
#[test]
fn a_hash_git_cannot_resolve_is_refused() {
    let f = fixture("bogus");
    let scope = vec!["crates/thing/**".to_string()];

    let error = verify_merge(
        &f.root,
        "0123456789abcdef0123456789abcdef01234567",
        "main",
        &scope,
    )
    .expect_err("an unresolvable hash must be refused");

    assert!(error.to_string().contains("rev-parse"), "{error}");
}
